#include "ImperialFileRuntime.hpp"
namespace elysium::faction {bool ImperialFileRuntime::add(FileFact f,bool legit,std::string&w){if(!legit){w="illegitimate source";return false;}if(!f.id||!f.type||!f.subject||!f.source){w="invalid fact";return false;}f.confidence=std::clamp(std::isfinite(f.confidence)?f.confidence:0.0,0.0,1.0);return facts_.emplace(f.id,std::move(f)).second;}std::vector<FileFact>ImperialFileRuntime::factsFor(StableId s)const{std::vector<FileFact>v;for(auto&[_,f]:facts_)if(f.subject==s)v.push_back(f);std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.time==b.time?a.id<b.id:a.time<b.time;});return v;}std::optional<FileFact>ImperialFileRuntime::bestFact(StableId s,ContentId t)const{std::optional<FileFact>b;for(auto&[_,f]:facts_)if(f.subject==s&&f.type==t&&(!b||f.confidence>b->confidence||(f.confidence==b->confidence&&f.time>b->time)))b=f;return b;}}
